def area_graph():
 a,b,c=(130,170),(440,105),(210,65)
 paths=[path([(80,295),(80,30)]),path([(45,260),(480,260)]),path([a,b,c,a],fill='#dcfce7',stroke='#166534')]
 for t in [i/12 for i in range(1,12)]:
  paths.append(path([(a[0]+t*(c[0]-a[0]),a[1]+t*(c[1]-a[1])),(a[0]+t*(b[0]-a[0]),a[1]+t*(b[1]-a[1]))],stroke='#166534'))
 for p in [a,b,c]:paths.append(path([p,(p[0],260)],dash=True))
 return geometry('Figure 7.30','Figure 7.30 — source triangular region and its three perpendicular projections on the x-axis',paths,[(77,22,'y'),(486,267,'x'),(57,285,'O'),(104,174,'P₁'),(440,97,'P₂'),(195,55,'P₃'),(107,289,'A(x₁,0)'),(408,289,'B(x₂,0)'),(180,318,'C(x₃,0)'),(132,230,'y₁'),(206,230,'y₃'),(435,230,'y₂')],size=(540,350))
PAGES=[page('107_page_2.jpg',206,[heading('Example 26'),paragraph('Let ABC be a triangle with vertices A(0,0), B(8,6) and C(12,0). Show that the altitudes AD, BE and CF of the triangle ABC are concurrent.'),heading('Solution'),paragraph('The vertices A(x₁,y₁) = A(0,0), B(x₂,y₂) = B(8,6) and C(x₃,y₃) = C(12,0) of the triangle ABC are used in the determinant (iii) to obtain:'),det(AROWS,'= 0 ⇒'),det([[-4,6,0],[12,0,-96],[-8,-6,96]],'= 0'),eq(r'-4(-576)-6(1152-768)=0\ \Rightarrow\ 2304-6(384)=0\ \Rightarrow\ 2304-2304=0'),paragraph('The determinant (iii) equals zero. Hence, the altitudes AD, BE and CF of the triangle ABC are concurrent.'),note('For the stated nondegenerate triangle, the learning solution also finds the common finite orthocenter and tests all three equations. The inherited general determinant’s x₃−y₁ typo was identified in the preceding proof; it has no numerical effect in this particular example because x₁ = y₁ = 0.'),heading('7.8 Area of a Triangular Region'),paragraph('Let ABC be a triangle whose vertices are P₁(x₁,y₁), P₂(x₂,y₂) and P₃(x₃,y₃). Project P₁A, P₂B and P₃C upon the x-axis that develops the trapezia P₁ACP₃, P₃CBP₂ and P₁ABP₂.'),area_graph(),paragraph('The area A of the triangular region P₁P₂P₃ is the sum of the areas of the trapezia P₁ACP₃, P₃CBP₂ and P₁ABP₂ minus the area of the trapezium P₁ABP₂.'),eq(r'A=\frac12[(y_1+y_3)(x_3-x_1)]+\frac12[(y_3+y_2)(x_2-x_3)]-\frac12[(y_1+y_2)(x_2-x_1)]'),eq(r'=\frac12[x_3y_1-x_1y_1+x_3y_3-x_1y_3+x_2y_3-x_3y_3+x_2y_2-x_3y_2-x_2y_1+x_1y_1-x_2y_2+x_1y_2]','i'),eq(r'=\frac12[x_1(y_2-y_3)+x_2(y_3-y_1)+x_3(y_1-y_2)]'),det([['x_1','y_1','1'],['x_2','y_2','1'],['x_3','y_3','1']],'(ii)',prefix='A = 1/2'),paragraph('It is important to note that the area A of the triangular region P₁P₂P₃ equals zero, when the vertices of the triangular region are collinear points.'),note('The paragraph redundantly includes P₁ABP₂ in both the sum and the subtraction; the displayed calculation correctly adds the first two trapezia and subtracts P₁ABP₂ once for the depicted ordering. The general determinant gives signed area. Geometric area is one half the absolute value of the determinant; reversing two vertex rows changes the sign, not the geometric area. The cross-product formula |(P₂−P₁)×(P₃−P₁)|/2 gives the same nonnegative result and handles any coordinates without trapezium-order assumptions.'),heading('Example 27'),paragraph('Find the area of the triangular region P₁P₂P₃ whose vertices are P₁(4,−5), P₂(5,−6) and P₃(3,1).'),heading('Solution'),paragraph('Result (i) is used for points P₁(4,−5), P₂(5,−6), P₃(3,1) to obtain the area of the triangular region P₁P₂P₃:'),det([[4,-5,1],[5,-6,1],[3,1,1]],'first row expansion',prefix='A = 1/2'),eq(r'=\frac12[4(-6-1)+5(5-3)+(5+18)]=\frac12[-28+10+23]=\frac52\ \mathrm{square\ units}')])]
PAGES[0].update(title='PLANE ANALYTIC GEOMETRY STRAIGHT LINE',visualStatus='Complete source altitude example and triangle-area proof with exact determinant expansions and native projection diagram',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':107,'side':'right','reason':'Area expansion enlarged and checked; all source vertices, signs and omitted-absolute-value condition reviewed'})
EXAMPLES=[]
for n,q,steps,ans in [
('26','For A(0,0), B(8,6), C(12,0), show that the three altitudes are concurrent.',['BC has direction (4,−6). The altitude from A is 4x−6y = 0, or 2x−3y = 0.','CA is horizontal, so the altitude from B is vertical: x = 8.','AB has direction (8,6). The altitude from C is 8(x−12)+6y = 0, or 4x+3y−48 = 0.','Intersect x = 8 with 2x−3y = 0: y = 16/3.','At H(8,16/3), the third equation gives 32+16−48 = 0, so all three altitudes share this finite point.','The equations pass through their respective vertices and their line normals are the corresponding opposite-side directions, confirming perpendicularity.','The source determinant also equals 2304−6·384 = 0, consistent with the explicit common-point check.'],'Concurrent at the orthocenter H(8,16/3).'),
('27','Find the area of P₁(4,−5), P₂(5,−6), P₃(3,1).',['Use the geometric-area formula A = |(P₂−P₁)×(P₃−P₁)|/2.','The first displacement is P₂−P₁ = (1,−1).','The second displacement is P₃−P₁ = (−1,6).','The scalar cross product is 1·6−(−1)(−1) = 6−1 = 5.','Take half its absolute value: A = |5|/2 = 5/2 square units.','Independently expand the coordinate determinant: 4(−7)+5(6)+3(1) = −28+30+3 = 5, giving the same area.','The nonzero result confirms that the three points are not collinear; reversing the vertex order would negate the determinant but preserve area.'],'5/2 square units.')]:
 EXAMPLES.append({'num':n,'title':'Concurrent Altitudes' if n=='26' else 'Triangle Area','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':206,'jpg':'107_page_2.jpg','verification':'Complete source question, exact vertices and determinant calculation visually checked'}]})
